"""Source-bound frame measurements for NRS 484D.215(1).

This measures Native geometry and lamp readback. Whether a physical beam reveals
people safely, projects glaring rays into eyes, or meets NRS 484D.210(2) stays
for original calibrated pixels and independent review.
"""
from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path

FEET_TO_METERS = 0.3048
LEGAL_DISTANCE_M = 500 * FEET_TO_METERS
VIEWS = ("overview", "approach", "reference_corner", "driver_reference")


def _hash(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _source(root: Path, name: str, digest: str) -> Path:
    if "/" in name or "\\" in name or name in ("", ".", ".."):
        raise ValueError("source path must be a simple original filename")
    path = root / name
    if not path.is_file() or path.is_symlink() or _hash(path) != digest:
        raise ValueError("missing or changed original source: " + name)
    return path


def _rows(path: Path) -> list[dict]:
    rows = [json.loads(x) for x in path.read_text().splitlines() if x]
    if not rows or any(not isinstance(x, dict) for x in rows):
        raise ValueError("empty or malformed original frame rows")
    return rows


def _xyz(value: object, label: str) -> tuple[float, float, float]:
    if not isinstance(value, list) or len(value) != 3 or any(type(x) not in (float, int) or not math.isfinite(x) for x in value):
        raise ValueError("missing original 3D coordinate: " + label)
    return tuple(float(x) for x in value)


def _distance(a: tuple[float, float, float], b: tuple[float, float, float]) -> float:
    return math.dist(a, b)


def _body_gap(a: tuple[float, float, float], b: tuple[float, float, float], ra: float, rb: float) -> float:
    if ra <= 0 or rb <= 0:
        raise ValueError("original body radii must be positive")
    return max(0.0, _distance(a, b) - ra - rb)


def measure(root: Path, source_hashes: dict[str, str], *, expected_frames: int = 900,
            case: dict | None = None) -> dict:
    """Validate original 20 Hz joins and report distance/beam observations.

    actor-state.jsonl requires original positions for ego, oncoming, a person
    ahead, and a separate target vehicle ahead. A source-reviewed site packet
    establishes highway polygon, nighttime applicability, contour and loading.
    Pixel reviews are separate and remain unresolved in this output.
    """
    root = Path(root)
    names = ("actor-state.jsonl", "camera-frame-map.jsonl", "site-packet.json")
    if set(source_hashes) != set(names):
        raise ValueError("all original source hashes required")
    paths = {name: _source(root, name, source_hashes[name]) for name in names}
    site = json.loads(paths["site-packet.json"].read_text())
    if (site.get("format") != "beam-road-site-v1" or
            site.get("source_reviewed") is not True or
            site.get("nevada_highway_public_access_reviewed") is not True or
            site.get("lighting_time_source_reviewed") is not True or
            site.get("lighting_time_qualifies") is not True or
            site.get("lamp_mounts_reviewed") is not True or
            site.get("driver_eye_sources_reviewed") is not True or
            site.get("contour_and_load_reviewed") is not True or
            not isinstance(site.get("source_refs"), list) or not site["source_refs"]):
        raise ValueError("reviewed qualifying highway, time, lamp, eye and contour source required")
    states = _rows(paths["actor-state.jsonl"])
    maps = _rows(paths["camera-frame-map.jsonl"])
    if len(states) != expected_frames or len(maps) != expected_frames or expected_frames < 2:
        raise ValueError("original 20 Hz duration or camera source count differs")
    base_frame = states[0].get("frame")
    if type(base_frame) is not int:
        raise ValueError("original frame ID required")
    first_t = states[0].get("time_s")
    if type(first_t) not in (int, float) or not math.isfinite(first_t):
        raise ValueError("original time required")
    ids: dict[str, object] = {}
    rows = []
    for index, (state, frame_map) in enumerate(zip(states, maps)):
        frame = base_frame + index
        if state.get("frame") != frame or frame_map.get("frame") != frame:
            raise ValueError("original frame identity is not contiguous")
        t = state.get("time_s")
        if type(t) not in (float, int) or not math.isfinite(t) or abs(t - (first_t + index / 20)) > .011:
            raise ValueError("original clock is not 20 Hz")
        for view in VIEWS:
            if frame_map.get(view + "_source_frame") != frame:
                raise ValueError("missing synchronized original camera frame: " + view)
        actors = state.get("actors")
        if not isinstance(actors, dict) or set(actors) != {"ego", "oncoming", "person", "target_vehicle"}:
            raise ValueError("all original participant sources required")
        centers = {}
        for role, actor in actors.items():
            if not isinstance(actor, dict) or type(actor.get("id")) not in (str, int):
                raise ValueError("original actor identity missing: " + role)
            if role in ids and ids[role] != actor["id"]:
                raise ValueError("original actor identity changed: " + role)
            ids[role] = actor["id"]
            centers[role] = _xyz(actor.get("center_m"), role + " center")
        ego = actors["ego"]
        incoming = actors["oncoming"]
        for role in ("ego", "oncoming"):
            actor = actors[role]
            if type(actor.get("speed_mps")) not in (float, int) or actor["speed_mps"] < 0 or not math.isfinite(actor["speed_mps"]):
                raise ValueError("original vehicle speed missing")
            if type(actor.get("body_radius_m")) not in (float, int) or actor["body_radius_m"] <= 0:
                raise ValueError("original vehicle body radius missing")
        if type(ego.get("lamp_state_bits")) is not int or type(ego.get("lamp_command_bits")) is not int:
            raise ValueError("original lamp command and readback required")
        if type(ego.get("on_traveled_highway_or_adjacent_shoulder")) is not bool or not ego["on_traveled_highway_or_adjacent_shoulder"]:
            raise ValueError("qualifying ego location not established")
        if type(incoming.get("opposing_route")) is not bool or not incoming["opposing_route"]:
            raise ValueError("oncoming route not established")
        eye_ego = _xyz(ego.get("driver_eye_m"), "ego eye")
        eye_incoming = _xyz(incoming.get("driver_eye_m"), "oncoming eye")
        body_gap = _body_gap(centers["ego"], centers["oncoming"], ego["body_radius_m"], incoming["body_radius_m"])
        eye_gap = _distance(eye_ego, eye_incoming)
        rows.append({"original_frame": frame, "time_s": round(float(t), 3),
                     "oncoming_body_gap_m": round(body_gap, 4),
                     "oncoming_eye_gap_m": round(eye_gap, 4),
                     "body_gap_within_500_ft": body_gap <= LEGAL_DISTANCE_M,
                     "eye_gap_within_500_ft": eye_gap <= LEGAL_DISTANCE_M,
                     "person_center_distance_m": round(_distance(centers["ego"], centers["person"]), 4),
                     "target_vehicle_center_distance_m": round(_distance(centers["ego"], centers["target_vehicle"]), 4),
                     "lamp_command_bits": ego["lamp_command_bits"],
                     "lamp_state_bits": ego["lamp_state_bits"]})
    if case is not None:
        if case.get("branch") == "general":
            if any(row["body_gap_within_500_ft"] or row["eye_gap_within_500_ft"] for row in rows):
                raise ValueError("general beam comparison entered oncoming 500-foot condition")
        elif case.get("branch") == "oncoming":
            if not any(row["body_gap_within_500_ft"] or row["eye_gap_within_500_ft"] for row in rows):
                raise ValueError("oncoming case never reached 500-foot condition")
        else:
            raise ValueError("unknown exact beam case branch")
    return {"format": "beam-road-original-measurement-v1", "frame_count": expected_frames,
            "first_original_frame": base_frame, "last_original_frame": base_frame + expected_frames - 1,
            "actor_ids": ids, "source_hashes": source_hashes, "rows": rows,
            "legal_distance_m": LEGAL_DISTANCE_M,
            "unresolved": ["Body and eye endpoints are both retained; legal 500-foot endpoint interpretation is unresolved.",
                           "Original calibrated pixels and reviewed eye ROI are required to assess actual glare.",
                           "Visibility at a safe distance has no numerical legal threshold in the supplied law.",
                           "CARLA low-beam bits alone do not prove the NRS 484D.210(2) lowermost distribution."]}

"""Source-gated Native construction plan and injected CARLA adapter contract."""
from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path

from beam_measure import FEET_TO_METERS, VIEWS

ASSIGNMENT = "testing__C230259__NRS-484D-215-1__motor_vehicle_driver"
MODES = {"high", "low", "off"}


def _point(value: object, label: str) -> list[float]:
    if (not isinstance(value, list) or len(value) != 3 or
            any(type(x) not in (int, float) or not math.isfinite(x) for x in value)):
        raise ValueError("source-reviewed 3D point required: " + label)
    return [float(x) for x in value]


def _route(value: object, label: str) -> list[list[float]]:
    if not isinstance(value, list) or len(value) < 2:
        raise ValueError("source-reviewed route required: " + label)
    points = [_point(point, label) for point in value]
    if all(math.dist(points[i], points[i + 1]) < .01 for i in range(len(points) - 1)):
        raise ValueError("source-reviewed route has no motion: " + label)
    return points


def _polygon(value: object) -> list[list[float]]:
    if not isinstance(value, list) or len(value) < 3:
        raise ValueError("reviewed traveled-highway/shoulder polygon required")
    points = []
    for point in value:
        if (not isinstance(point, list) or len(point) != 2 or
                any(type(x) not in (int, float) or not math.isfinite(x) for x in point)):
            raise ValueError("reviewed highway polygon coordinate invalid")
        points.append([float(x) for x in point])
    area = abs(sum(points[i][0] * points[(i + 1) % len(points)][1] -
                   points[(i + 1) % len(points)][0] * points[i][1]
                   for i in range(len(points))) / 2)
    if area < 1:
        raise ValueError("reviewed highway polygon degenerate")
    return points


def validate_site(packet_path: Path, case: dict, *, diagnostic: bool = False) -> dict:
    raw = Path(packet_path).read_bytes()
    site = json.loads(raw)
    if not case["case_id"].startswith(ASSIGNMENT + "__") or case.get("kind") != "delivery":
        raise ValueError("exact delivery case required")
    if (site.get("format") != "beam-road-site-v1" or
            site.get("case_id") != case["case_id"] or
            site.get("cell_id") != "C230259" or
            site.get("actor") != "motor_vehicle_driver" or
            site.get("diagnostic_fixture") is not diagnostic):
        raise ValueError("exact reviewed Native site identity differs")
    if not diagnostic:
        for field in ("source_reviewed", "nevada_highway_public_access_reviewed",
                      "lighting_time_source_reviewed", "lighting_time_qualifies",
                      "lamp_mounts_reviewed", "driver_eye_sources_reviewed",
                      "contour_and_load_reviewed", "roi_projection_reviewed"):
            if site.get(field) is not True:
                raise ValueError("missing source review: " + field)
    refs = site.get("source_refs")
    if not isinstance(refs, list) or not refs:
        raise ValueError("original map/time/vehicle source references required")
    for ref in refs:
        if not isinstance(ref, dict) or not ref.get("path") or len(ref.get("sha256", "")) != 64:
            raise ValueError("original source reference incomplete")
        source = Path(ref["path"])
        if not source.is_file() or hashlib.sha256(source.read_bytes()).hexdigest() != ref["sha256"]:
            raise ValueError("original map/time/vehicle source hash differs")
    if not isinstance(site.get("map_name"), str) or len(site.get("map_sha256", "")) != 64:
        raise ValueError("reviewed Native map identity required")
    if site.get("requested_beam") != case["requested_beam"] or site["requested_beam"] not in MODES:
        raise ValueError("requested beam differs from exact case")
    if site.get("requested_contour") != case["requested_contour"] or site.get("requested_load") != case["requested_load"]:
        raise ValueError("contour/load comparison variable differs")
    if site.get("requested_start_body_gap_ft") != case["requested_start_body_gap_ft"]:
        raise ValueError("500-foot construction variable differs")
    routes = site.get("routes")
    if not isinstance(routes, dict) or set(routes) != {"ego", "oncoming"}:
        raise ValueError("ego and oncoming reviewed routes required")
    ego = _route(routes["ego"], "ego")
    oncoming = _route(routes["oncoming"], "oncoming")
    _polygon(site.get("highway_or_shoulder_polygon_xy_m"))
    ego_vector = [ego[-1][i] - ego[0][i] for i in range(2)]
    incoming_vector = [oncoming[-1][i] - oncoming[0][i] for i in range(2)]
    dot = sum(ego_vector[i] * incoming_vector[i] for i in range(2))
    if dot >= 0:
        raise ValueError("oncoming route must oppose ego route")
    targets = site.get("targets")
    if not isinstance(targets, dict) or set(targets) != {"person", "vehicle"}:
        raise ValueError("person and vehicle ahead required")
    for role in ("person", "vehicle"):
        _point(targets[role]["transform_m"], role)
        if not targets[role].get("blueprint_id"):
            raise ValueError("target blueprint required")
    if not isinstance(site.get("blueprints"), dict) or set(site["blueprints"]) != {"ego", "oncoming"}:
        raise ValueError("original motor vehicle blueprints required")
    for value in site["blueprints"].values():
        if not isinstance(value, str) or not value.startswith("vehicle."):
            raise ValueError("motor vehicle blueprint required")
    body_radii = site.get("reviewed_body_radii_m")
    if (not isinstance(body_radii, dict) or set(body_radii) != {"ego", "oncoming"} or
            any(type(value) not in (int, float) or not math.isfinite(value) or value <= 0
                for value in body_radii.values())):
        raise ValueError("source-reviewed original vehicle body radii required")
    eye_offsets = site.get("driver_eye_offsets_m")
    if not isinstance(eye_offsets, dict) or set(eye_offsets) != {"ego", "oncoming"}:
        raise ValueError("source-reviewed driver-eye offsets required")
    for role, offset in eye_offsets.items():
        _point(offset, role + " driver eye offset")
    speeds = site.get("speed_requests_mps")
    if (not isinstance(speeds, dict) or set(speeds) != {"ego", "oncoming"} or
            any(type(value) not in (int, float) or not math.isfinite(value) or value <= 0
                for value in speeds.values())):
        raise ValueError("positive motor vehicle speed requests required")
    cameras = site.get("cameras")
    if not isinstance(cameras, dict) or set(cameras) != set(VIEWS):
        raise ValueError("four reviewed camera poses required")
    for view, spec in cameras.items():
        if spec.get("blueprint_id") != "sensor.camera.rgb":
            raise ValueError("camera blueprint differs: " + view)
        _point(spec.get("transform_m"), view)
        fov = spec.get("fov_deg")
        if type(fov) not in (int, float) or not 1 <= fov <= 120:
            raise ValueError("reviewed camera field of view required: " + view)
    alternate = site.get("alternate_cameras")
    if alternate is not None:
        if not isinstance(alternate, dict) or set(alternate) != set(VIEWS):
            raise ValueError("four reviewed alternate camera poses required")
        for view, spec in alternate.items():
            if spec.get("blueprint_id") != "sensor.camera.rgb":
                raise ValueError("alternate camera blueprint differs: " + view)
            _point(spec.get("transform_m"), "alternate " + view)
            fov = spec.get("fov_deg")
            if type(fov) not in (int, float) or not 1 <= fov <= 120:
                raise ValueError("reviewed alternate camera field of view required: " + view)
    if not diagnostic and (len(site.get("camera_calibration_sha256", "")) != 64 or
                           len(site.get("projection_review_sha256", "")) != 64):
        raise ValueError("source-reviewed camera calibration and projection required")
    if case["branch"] == "oncoming":
        feet = case["requested_start_body_gap_ft"]
        if type(feet) not in (int, float) or feet <= 0:
            raise ValueError("oncoming start separation required")
        observed = (math.dist(ego[0], oncoming[0]) -
                    body_radii["ego"] - body_radii["oncoming"]) / FEET_TO_METERS
        if abs(observed - feet) > 10:
            raise ValueError("reviewed initial oncoming body separation differs from construction target")
    elif case["branch"] == "general":
        # Isolate the general illumination comparison from the special
        # within-500-foot oncoming condition for the entire reviewed route.
        start_gap_ft = (math.dist(ego[0], oncoming[0]) -
                        body_radii["ego"] - body_radii["oncoming"]) / FEET_TO_METERS
        if abs(start_gap_ft - case["requested_start_body_gap_ft"]) > 10:
            raise ValueError("general beam original start body gap differs")
        if min(math.dist(ego[0], oncoming[0]), math.dist(ego[-1], oncoming[-1])) - sum(body_radii.values()) <= 500 * FEET_TO_METERS + 10:
            raise ValueError("general beam case enters oncoming 500-foot condition")
    else:
        raise ValueError("unknown exact beam branch")
    return site


def construct(adapter, site: dict, *, case: dict) -> dict:
    """Execute a reviewed scene using a transaction-owned adapter.

    The adapter owns actor destruction and world-settings restoration even if a
    later sensor/actor spawn fails. The returned IDs are source identifiers,
    never an assertion that the requested physical light distribution occurred.
    """
    if site.get("case_id") != case["case_id"] or site.get("requested_beam") != case["requested_beam"]:
        raise ValueError("exact construction selection differs")
    actors = {}
    for role in ("ego", "oncoming"):
        actors[role] = adapter.spawn_vehicle(site["blueprints"][role], site["routes"][role][0])
        if actors[role] is None:
            raise ValueError("Native vehicle spawn failed: " + role)
        adapter.set_route(actors[role], site["routes"][role])
    for role in ("person", "vehicle"):
        target = site["targets"][role]
        actors[role] = adapter.spawn_target(target["blueprint_id"], target["transform_m"])
        if actors[role] is None:
            raise ValueError("Native target spawn failed: " + role)
    adapter.set_beam(actors["ego"], case["requested_beam"])
    cameras = {}
    for view, spec in site["cameras"].items():
        cameras[view] = adapter.spawn_camera(view, spec, attach_to=actors["ego"])
        if cameras[view] is None:
            raise ValueError("Native camera spawn failed: " + view)
    return {"actor_ids": {role: actor.id for role, actor in actors.items()},
            "camera_ids": {view: camera.id for view, camera in cameras.items()},
            "requested_beam": case["requested_beam"], "legal_judgment": None}

"""Four original CARLA camera archives for a moving road-beam Native attempt.

Sensors are caller-owned. This adapter owns the listeners and lossless archives;
actual beam emission and physical aim require later original-image review.
"""
from __future__ import annotations

import hashlib
import io
from pathlib import Path
from queue import Empty, Queue
import subprocess
import zipfile

from PIL import Image

VIEWS = ("overview", "approach", "reference_corner", "driver_reference")
PROFILE_DIMENSIONS = {
    "overview": (1920, 1080),
    "approach": (1280, 720),
    "reference_corner": (1280, 720),
    "driver_reference": (1280, 720),
}


def encode_original_videos(output: Path, frame_rows: list[dict], *, rate_hz: int = 20) -> dict:
    """Encode the retained original PNG frames without altering their archives."""
    output = Path(output)
    if rate_hz != 20 or not frame_rows or any(
            row['video_frame'] != index or type(row['carla_frame']) is not int
            for index, row in enumerate(frame_rows)):
        raise ValueError('original 20 Hz video frame map invalid')
    references = {}
    for view in VIEWS:
        archive_path = output / (view + '.zip')
        movie = output / (view + '.mkv')
        if movie.exists():
            raise ValueError('original movie already exists: ' + movie.name)
        with zipfile.ZipFile(archive_path) as archive:
            expected = [str(row['carla_frame']) + '.png' for row in frame_rows]
            if archive.namelist() != expected:
                raise ValueError('original camera archive/frame map differs: ' + view)
            command = ['ffmpeg', '-hide_banner', '-loglevel', 'error', '-nostdin', '-y',
                       '-framerate', str(rate_hz), '-f', 'image2pipe', '-vcodec', 'png',
                       '-i', 'pipe:0', '-an', '-c:v', 'ffv1', '-level', '3', str(movie)]
            process = subprocess.Popen(command, stdin=subprocess.PIPE,
                                       stdout=subprocess.DEVNULL, stderr=subprocess.PIPE)
            try:
                for name in expected:
                    process.stdin.write(archive.read(name))
                process.stdin.close()
                error = process.stderr.read().decode('utf-8', errors='replace')
                code = process.wait()
            except Exception:
                process.kill()
                process.wait()
                raise
            if code != 0 or not movie.is_file() or movie.stat().st_size == 0:
                raise ValueError('original camera encode failed: ' + view + ': ' + error[-500:])
        references[view] = {'path': movie.name,
                            'sha256': hashlib.sha256(movie.read_bytes()).hexdigest(),
                            'source_frame_count': len(frame_rows)}
    return references


class CameraRecorder:
    def __init__(self, sensors: dict, output: Path, *, timeout_seconds: float = 5.0,
                 dimensions: dict | None = None):
        if set(sensors) != set(VIEWS) or timeout_seconds <= 0:
            raise ValueError("four sensors and positive timeout required")
        dimensions = PROFILE_DIMENSIONS if dimensions is None else dimensions
        if set(dimensions) != set(VIEWS) or any(
                not isinstance(dimensions[view], (tuple, list)) or
                len(dimensions[view]) != 2 or
                any(type(size) is not int or size <= 0 for size in dimensions[view])
                for view in VIEWS):
            raise ValueError("four positive camera dimensions required")
        self.sensors = sensors
        self.output = Path(output)
        self.timeout_seconds = timeout_seconds
        self.dimensions = {view: tuple(dimensions[view]) for view in VIEWS}
        self.queues = {view: Queue() for view in VIEWS}
        self.listening = []
        self.archives = {}
        self.frames = 0
        self.closed = False

    def start(self):
        if self.listening or self.closed:
            raise ValueError("camera recorder already started or closed")
        self.output.mkdir(parents=True, exist_ok=True)
        if any((self.output / (view + ".zip")).exists() for view in VIEWS):
            raise ValueError("original camera archive already exists")
        try:
            for view in VIEWS:
                sensor = self.sensors[view]
                sensor.listen(lambda image, name=view: self.queues[name].put(image))
                self.listening.append(sensor)
            self.archives = {view: zipfile.ZipFile(self.output / (view + ".zip"), "w",
                             compression=zipfile.ZIP_STORED) for view in VIEWS}
        except Exception:
            self.close()
            raise

    @staticmethod
    def _png(image, expected_dimensions: tuple[int, int]) -> bytes:
        width, height = image.width, image.height
        if (type(width) is not int or type(height) is not int or
                width <= 0 or height <= 0):
            raise ValueError("original camera dimensions invalid")
        if (width, height) != expected_dimensions:
            raise ValueError("original camera dimensions differ from capture profile")
        raw = bytes(image.raw_data)
        if len(raw) != width * height * 4:
            raise ValueError("original camera BGRA byte count mismatch")
        rgb = Image.frombytes("RGBA", (width, height), raw, "raw", "BGRA").convert("RGB")
        stream = io.BytesIO()
        rgb.save(stream, format="PNG")
        return stream.getvalue()

    def __call__(self, frame: int) -> dict:
        if self.closed or len(self.archives) != 4 or type(frame) is not int:
            raise ValueError("camera recorder not started")
        encoded = {}
        for view in VIEWS:
            try:
                image = self.queues[view].get(timeout=self.timeout_seconds)
            except Empty as exc:
                raise ValueError("original camera callback missing: " + view) from exc
            if image.frame != frame:
                raise ValueError("original camera callback frame mismatch: " + view)
            encoded[view] = self._png(image, self.dimensions[view])
        for view in VIEWS:
            self.archives[view].writestr(f"{frame}.png", encoded[view])
        self.frames += 1
        return {view: frame for view in VIEWS}

    def finish(self, expected_frames: int) -> dict:
        if self.closed or self.frames != expected_frames:
            raise ValueError("original camera archive frame count incomplete")
        self.close()
        media = {}
        for view in VIEWS:
            path = self.output / (view + ".zip")
            with zipfile.ZipFile(path) as archive:
                if len(archive.namelist()) != expected_frames:
                    raise ValueError("original camera archive incomplete")
            media[view] = {"path": path.name,
                           "sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
                           "source_frame_count": expected_frames}
        return media

    def close(self):
        for sensor in self.listening:
            sensor.stop()
        self.listening.clear()
        for archive in self.archives.values():
            archive.close()
        self.closed = True

"""Original pixel measurements of persons, vehicles, and oncoming eye region.

Frame-specific ROIs must be sourced from reviewed original camera calibration
and participant projection. RGB luma is an image observable, never calibrated
illuminance, safe revelation, projected glare rays, or a legal conclusion.
"""
from __future__ import annotations

import hashlib
import io
import json
from pathlib import Path
import subprocess
from zipfile import ZipFile

from PIL import Image

VIEWS = ("approach", "driver_reference")
ROLES = {"person": "approach", "target_vehicle": "approach", "oncoming_eye": "driver_reference"}


def _hash(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _source(root: Path, name: str, digest: str) -> Path:
    if name != Path(name).name or name in ("", ".", ".."):
        raise ValueError("original pixel source must be attempt-relative")
    path = root / name
    if not path.is_file() or path.is_symlink() or _hash(path) != digest:
        raise ValueError("original pixel source missing or changed: " + name)
    return path


def _box(value, size, role):
    if (not isinstance(value, list) or len(value) != 4 or
            any(type(x) is not int for x in value)):
        raise ValueError("reviewed original ROI box missing: " + role)
    left, top, right, bottom = value
    if not (0 <= left < right <= size[0] and 0 <= top < bottom <= size[1]):
        raise ValueError("reviewed original ROI outside camera: " + role)
    if (right - left) * (bottom - top) < 4:
        raise ValueError("reviewed original ROI too small: " + role)
    return tuple(value)


def _luma(image, box):
    cropped = image.crop(box).convert("RGB")
    pixels = cropped.getdata()
    total = 0.0
    for red, green, blue in pixels:
        total += .2126 * red + .7152 * green + .0722 * blue
    return round(total / len(pixels), 4)


def measure(root: Path, source_hashes: dict[str, str], *, expected_frames: int = 900,
            diagnostic: bool = False, include_eye: bool = True) -> dict:
    root = Path(root)
    common = {"roi-frames.jsonl", "camera-frame-map.jsonl"}
    zipped = {"approach.zip", "driver_reference.zip"}
    movies = {"approach.mkv", "driver_reference.mkv"}
    if set(source_hashes) not in (common | zipped, common | movies):
        raise ValueError("original ROI, camera and frame-map hashes required")
    sources = {name: _source(root, name, source_hashes[name]) for name in source_hashes}
    rois = [json.loads(x) for x in sources["roi-frames.jsonl"].read_text().splitlines() if x]
    frame_map = [json.loads(x) for x in sources["camera-frame-map.jsonl"].read_text().splitlines() if x]
    if len(rois) != expected_frames or len(frame_map) != expected_frames or expected_frames < 2:
        raise ValueError("complete original frame-specific ROI join required")
    roles = {"person", "target_vehicle", "oncoming_eye"} if include_eye else {"person", "target_vehicle"}
    result = []
    for index, (roi, mapped) in enumerate(zip(rois, frame_map)):
        frame = mapped.get("frame")
        if type(frame) is not int or frame != frame_map[0].get("frame") + index or roi.get("frame") != frame:
            raise ValueError("original ROI frame identity differs")
        if roi.get("source_kind") != "reviewed_original_projection" or roi.get("diagnostic_fixture") is not diagnostic:
            raise ValueError("reviewed original projected ROI source required")
        if not diagnostic and (not roi.get("calibration_source_sha256") or not roi.get("projection_source_sha256")):
            raise ValueError("original projection/calibration source hash required")
        if not isinstance(roi.get("regions"), dict) or set(roi["regions"]) != roles:
            raise ValueError("person, vehicle and required oncoming-eye ROIs required")
        for view in VIEWS:
            if mapped.get(view + "_source_frame") != frame:
                raise ValueError("stale original camera frame join: " + view)
        result.append({"original_frame": frame})

    use_movie = set(source_hashes) == common | movies
    for view in VIEWS:
        expected_size = ((1280, 720) if use_movie else (16, 12)) if diagnostic else (1280, 720)
        if use_movie:
            path = sources[view + ".mkv"]
            command = ["ffmpeg", "-hide_banner", "-loglevel", "error", "-nostdin",
                       "-i", str(path), "-f", "rawvideo", "-pix_fmt", "rgb24", "pipe:1"]
            process = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            try:
                size = expected_size[0] * expected_size[1] * 3
                for index in range(expected_frames):
                    raw = process.stdout.read(size)
                    if len(raw) != size:
                        raise ValueError("original movie decoded fewer frames: " + view)
                    image = Image.frombytes("RGB", expected_size, raw)
                    for role in roles:
                        if ROLES[role] == view:
                            result[index][role + "_mean_luma_8bit"] = _luma(
                                image, _box(rois[index]["regions"][role], expected_size, role))
                if process.stdout.read(1):
                    raise ValueError("original movie decoded extra frames: " + view)
                error = process.stderr.read().decode("utf-8", errors="replace")
                if process.wait() != 0:
                    raise ValueError("original movie decode failed: " + view + ": " + error[-300:])
            except BaseException:
                process.kill()
                process.wait()
                raise
            finally:
                process.stdout.close()
                process.stderr.close()
        else:
            with ZipFile(sources[view + ".zip"]) as archive:
                expected_names = [str(row["frame"]) + ".png" for row in frame_map]
                if archive.namelist() != expected_names or len(set(archive.namelist())) != expected_frames:
                    raise ValueError("original camera archive frame inventory differs: " + view)
                for index, name in enumerate(expected_names):
                    with Image.open(io.BytesIO(archive.read(name))) as source_image:
                        if source_image.format != "PNG" or source_image.size != expected_size:
                            raise ValueError("original RGB PNG camera profile differs")
                        image = source_image.convert("RGB")
                    for role in roles:
                        if ROLES[role] == view:
                            result[index][role + "_mean_luma_8bit"] = _luma(
                                image, _box(rois[index]["regions"][role], expected_size, role))
    return {"format": "beam-road-original-pixels-v1", "frame_count": expected_frames,
            "source_hashes": source_hashes, "rows": result,
            "calibrated_illuminance_claimed": False, "physical_glare_claimed": False,
            "legal_verdict_claimed": False}

"""Independent saved-source comparison of fixed and deliberate case variables."""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

from analysis import build as analyze

ASSIGNMENT = "testing__C230259__NRS-484D-215-1__motor_vehicle_driver"


def _read(root: Path, name: str):
    path = root / name
    if not path.is_file() or path.is_symlink():
        raise ValueError("Missing required source: " + name)
    return json.loads(path.read_text())


def _config_fixed(config):
    return {key: config.get(key) for key in
            ("assignment_id", "law_id", "cell_id", "actor", "rate_hz",
             "frame_count", "duration_s", "camera_dimensions", "cameras",
             "required_atoms", "source_packets", "supported_case_ids")}


def _site_fixed(site, comparison_id):
    fields = ["format", "cell_id", "actor", "map_name", "map_sha256",
              "highway_or_shoulder_polygon_xy_m", "blueprints", "targets",
              "cameras", "speed_requests_mps", "driver_eye_offsets_m",
              "nevada_highway_public_access_reviewed", "lighting_time_source_reviewed",
              "lighting_time_qualifies"]
    if comparison_id not in ("lowermost_contour_load",):
        fields += ["requested_contour", "requested_load"]
    if comparison_id not in ("five_hundred_feet_lower", "five_hundred_feet_upper",
                             "lowermost_contour_load"):
        fields += ["routes", "requested_start_body_gap_ft"]
    return {key: site.get(key) for key in fields}


def _mean(values):
    if not values:
        raise ValueError("empty original comparison measurement")
    return sum(values) / len(values)


def _observed_difference(comparison_id, first, second):
    a = first["measurements"]
    b = second["measurements"]
    if comparison_id in ("general_beam_distribution", "general_no_distribution", "near_oncoming_glare"):
        first_bits = a["beam_requirement_3"]["value"]["lamp_readback_bits_by_frame"]
        second_bits = b["beam_requirement_3"]["value"]["lamp_readback_bits_by_frame"]
        changed = first_bits != second_bits
        return {"metric": "original lamp-state readback bits", "changed": changed,
                "first_unique_bits": sorted(set(first_bits)),
                "second_unique_bits": sorted(set(second_bits))}
    if comparison_id in ("five_hundred_feet_lower", "five_hundred_feet_upper"):
        first_gap = a["beam_requirement_2"]["value"]["oncoming_body_gap_m_by_frame"]
        second_gap = b["beam_requirement_2"]["value"]["oncoming_body_gap_m_by_frame"]
        delta = _mean(second_gap) - _mean(first_gap)
        return {"metric": "mean original oncoming body gap m",
                "changed": abs(delta) > .01, "second_minus_first_m": round(delta, 4)}
    if comparison_id == "lowermost_contour_load":
        return {"metric": "source-reviewed contour and load",
                "changed": True, "physical_lowermost_specification_confirmed": False}
    raise ValueError("unknown selected comparison")


def audit(first_attempt: Path, second_attempt: Path, comparison_id: str,
          *, diagnostic: bool = False, expected_frames: int = 900) -> dict:
    a_root = Path(first_attempt).resolve(strict=True)
    b_root = Path(second_attempt).resolve(strict=True)
    if a_root == b_root:
        raise ValueError("comparison needs two distinct original attempts")
    plan_path = Path(__file__).resolve().parent / "case-plan.json"
    plan = json.loads(plan_path.read_text())
    selected = next((x for x in plan["comparisons"] if x["comparison_id"] == comparison_id), None)
    if selected is None:
        raise ValueError("selected comparison missing from exact plan")
    a_config = _read(a_root, "config.json")
    b_config = _read(b_root, "config.json")
    if [a_config.get("selected_case_id"), b_config.get("selected_case_id")] != selected["case_ids"]:
        raise ValueError("comparison exact case order differs")
    if _config_fixed(a_config) != _config_fixed(b_config):
        raise ValueError("comparison fixed capture/identity conditions differ")
    a_site = _read(a_root, "site-packet.json")
    b_site = _read(b_root, "site-packet.json")
    if _site_fixed(a_site, comparison_id) != _site_fixed(b_site, comparison_id):
        raise ValueError("comparison fixed Native site conditions differ")
    a_report = analyze(a_root, expected_frames=expected_frames, diagnostic=diagnostic)
    b_report = analyze(b_root, expected_frames=expected_frames, diagnostic=diagnostic)
    difference = _observed_difference(comparison_id, a_report, b_report)
    if not difference["changed"]:
        raise ValueError("declared comparison variable did not change in original source")
    return {"format": "worker-comparison-audit", "assignment_id": ASSIGNMENT,
            "comparison_id": comparison_id, "case_ids": selected["case_ids"],
            "fixed_conditions": selected["fixed_conditions"],
            "deliberate_differences": selected["deliberate_differences"],
            "fixed_source_conditions_verified": True,
            "observed_difference": difference,
            "first_source_sha256": hashlib.sha256((a_root / "native-source-receipt.json").read_bytes()).hexdigest(),
            "second_source_sha256": hashlib.sha256((b_root / "native-source-receipt.json").read_bytes()).hexdigest(),
            "diagnostic_fixture": diagnostic,
            "physical_acceptance_claimed": False,
            "legal_verdict_claimed": False}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--comparison", required=True)
    parser.add_argument("--first-attempt", required=True)
    parser.add_argument("--second-attempt", required=True)
    parser.add_argument("--output", required=True)
    parser.add_argument("--diagnostic-fixture", action="store_true")
    args = parser.parse_args()
    result = audit(Path(args.first_attempt), Path(args.second_attempt), args.comparison,
                   diagnostic=args.diagnostic_fixture,
                   expected_frames=(json.loads((Path(args.first_attempt) / "native-source-receipt.json").read_text())["frame_count"]
                                    if args.diagnostic_fixture else 900))
    output = Path(args.output)
    if output.exists():
        raise ValueError("comparison audit output already exists")
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(json.dumps(result, indent=2) + "\n")
    print(json.dumps({"comparison_id": args.comparison, "passed": True,
                      "diagnostic_fixture": args.diagnostic_fixture}))


if __name__ == "__main__":
    main()
